import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry the_entry_name(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .s32 reduce_dim,
    .param .u64 n0,
    .param .u64 n1,
    .param .u64 n2,
    .param .u64 out_numel
)
{
    .reg .pred  %p<8>;
    .reg .b32   %r<8>;
    .reg .b64   %rd<80>;
    .reg .f32   %f<8>;

    // Load params
    ld.param.u64 %rd10, [input_ptr];
    ld.param.u64 %rd11, [output_ptr];
    ld.param.s32 %r0, [reduce_dim];
    ld.param.u64 %rd12, [n0];
    ld.param.u64 %rd13, [n1];
    ld.param.u64 %rd14, [n2];
    ld.param.u64 %rd15, [out_numel];

    // Compute linear thread index
    mov.u32 %r1, %tid.x;
    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mad.lo.s32 %r4, %r2, %r3, %r1;
    cvt.u64.u32 %rd0, %r4;

    // Bounds check
    setp.ge.u64 %p0, %rd0, %rd15;
    @%p0 bra RET;

    // Branch on reduce_dim
    setp.eq.s32 %p1, %r0, 0;
    @%p1 bra DIM0;
    setp.eq.s32 %p2, %r0, 1;
    @%p2 bra DIM1;
    // default: reduce over dim 2
    bra DIM2;

DIM0:
    // Reduce over dim 0
    // i1 = out_idx / n2; i2 = out_idx % n2
    div.u64 %rd20, %rd0, %rd14;   // i1
    rem.u64 %rd21, %rd0, %rd14;   // i2
    // base_elems = i1*n2 + i2
    mul.lo.u64 %rd22, %rd20, %rd14;
    add.u64 %rd23, %rd22, %rd21;  // base_elems
    // stride_elems = n1*n2
    mul.lo.u64 %rd24, %rd13, %rd14;
    // len = n0
    mov.u64 %rd25, %rd12;

    // addr = in + base_elems*4
    shl.b64 %rd26, %rd23, 2;
    add.u64 %rd27, %rd10, %rd26;

    // Load first element
    ld.global.f32 %f0, [%rd27];
    // remaining = len - 1
    sub.s64 %rd28, %rd25, 1;
    setp.le.s64 %p3, %rd28, 0;
    @%p3 bra STORE;

    // step_bytes = stride_elems*4
    shl.b64 %rd29, %rd24, 2;

LOOP_DIM0:
    add.u64 %rd27, %rd27, %rd29;
    ld.global.f32 %f1, [%rd27];
    setp.lt.f32 %p4, %f1, %f0;
    @%p4 mov.f32 %f0, %f1;
    add.s64 %rd28, %rd28, -1;
    setp.gt.s64 %p5, %rd28, 0;
    @%p5 bra LOOP_DIM0;
    bra STORE;

DIM1:
    // Reduce over dim 1
    // i0 = out_idx / n2; i2 = out_idx % n2
    div.u64 %rd30, %rd0, %rd14;  // i0
    rem.u64 %rd31, %rd0, %rd14;  // i2
    // stride12 = n1*n2
    mul.lo.u64 %rd32, %rd13, %rd14; // n1*n2
    // base_elems = i0*stride12 + i2
    mul.lo.u64 %rd33, %rd30, %rd32;
    add.u64 %rd34, %rd33, %rd31;  // base_elems
    // stride_elems = n2
    mov.u64 %rd35, %rd14;
    // len = n1
    mov.u64 %rd36, %rd13;

    // addr = in + base_elems*4
    shl.b64 %rd37, %rd34, 2;
    add.u64 %rd38, %rd10, %rd37;

    // Load first element
    ld.global.f32 %f0, [%rd38];
    // remaining = len - 1
    sub.s64 %rd39, %rd36, 1;
    setp.le.s64 %p6, %rd39, 0;
    @%p6 bra STORE;

    // step_bytes = stride_elems*4
    shl.b64 %rd40, %rd35, 2;

LOOP_DIM1:
    add.u64 %rd38, %rd38, %rd40;
    ld.global.f32 %f2, [%rd38];
    setp.lt.f32 %p7, %f2, %f0;
    @%p7 mov.f32 %f0, %f2;
    add.s64 %rd39, %rd39, -1;
    setp.gt.s64 %p6, %rd39, 0;
    @%p6 bra LOOP_DIM1;
    bra STORE;

DIM2:
    // Reduce over dim 2
    // i0 = out_idx / n1; i1 = out_idx % n1
    div.u64 %rd50, %rd0, %rd13;  // i0
    rem.u64 %rd51, %rd0, %rd13;  // i1
    // stride12 = n1*n2
    mul.lo.u64 %rd52, %rd13, %rd14; // n1*n2
    // base_elems = i0*stride12 + i1*n2 + 0
    mul.lo.u64 %rd53, %rd50, %rd52; // i0*(n1*n2)
    mul.lo.u64 %rd54, %rd51, %rd14; // i1*n2
    add.u64 %rd55, %rd53, %rd54;    // base_elems
    // len = n2
    mov.u64 %rd57, %rd14;

    // addr = in + base_elems*4
    shl.b64 %rd58, %rd55, 2;
    add.u64 %rd59, %rd10, %rd58;

    // Load first element
    ld.global.f32 %f0, [%rd59];
    // remaining = len - 1
    sub.s64 %rd60, %rd57, 1;
    setp.le.s64 %p0, %rd60, 0;
    @%p0 bra STORE;

    // step_bytes = 4
    mov.u64 %rd61, 4;

LOOP_DIM2:
    add.u64 %rd59, %rd59, %rd61;
    ld.global.f32 %f3, [%rd59];
    setp.lt.f32 %p1, %f3, %f0;
    @%p1 mov.f32 %f0, %f3;
    add.s64 %rd60, %rd60, -1;
    setp.gt.s64 %p2, %rd60, 0;
    @%p2 bra LOOP_DIM2;

STORE:
    // out[tid] = min
    shl.b64 %rd70, %rd0, 2;
    add.u64 %rd71, %rd11, %rd70;
    st.global.f32 [%rd71], %f0;

RET:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("the_entry_name")

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.dim() != 3:
            raise ValueError("ModelNew expects a 3D tensor input.")
        if x.dtype != torch.float32:
            raise ValueError("ModelNew expects input dtype=torch.float32.")
        dim = self.dim
        if dim < 0:
            dim += x.dim()
        if dim < 0 or dim >= x.dim():
            raise ValueError("Invalid reduction dimension.")
        n0, n1, n2 = int(x.size(0)), int(x.size(1)), int(x.size(2))
        out_shape = [n0, n1, n2]
        del out_shape[dim]
        out_numel = 1
        for v in out_shape:
            out_numel *= int(v)
        out = torch.empty(out_shape, dtype=x.dtype, device=x.device)

        module = _get_ptx_module()
        block_x = 256
        grid_x = (out_numel + block_x - 1) // block_x
        module.launch(
            "the_entry_name",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, out, i32(int(dim)), u64(n0), u64(n1), u64(n2), u64(out_numel)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

